from livekit.agents import llm


class CRMFunctions:
    def __init__(self, agent_config):
        self.webhook_url = os.getenv("CRM_WEBHOOK_URL")
        self.webhook_secret = os.getenv("CRM_WEBHOOK_SECRET")
        self.client = httpx.AsyncClient(timeout=10.0)

    def get_functions(self) -> List[Callable]:
        return [
            self.log_call,
            self.create_lead,
            self.update_contact,
            self.add_note,
        ]

    async def _post(self, event: str, payload: Dict[str, Any]) -> str:
        if not self.webhook_url:
            return json.dumps({"status": "skipped", "reason": "no_webhook_configured"})
        try:
            headers = {"Content-Type": "application/json"}
            if self.webhook_secret:
                headers["X-Webhook-Signature"] = self.webhook_secret
            resp = await self.client.post(self.webhook_url, json={
                "event": event,
                "timestamp": __import__("datetime").datetime.utcnow().isoformat(),
                "payload": payload,
            }, headers=headers)
            resp.raise_for_status()
            return json.dumps({"status": "logged", "event": event})
        except Exception as e:
            return json.dumps({"error": str(e), "status": "failed"})

    @llm.ai_callable(description="Log call details to CRM")
    async def log_call(
