import httpx
import json
import os
from typing import Callable, List
from livekit.agents import llm


class NotificationFunctions:
    def __init__(self, agent_config):
        self.twilio_sid = os.getenv("TWILIO_ACCOUNT_SID")
        self.twilio_token = os.getenv("TWILIO_AUTH_TOKEN")
        self.twilio_from = os.getenv("TWILIO_PHONE_NUMBER")
        self.sendgrid_key = os.getenv("SENDGRID_API_KEY")
        self.from_email = os.getenv("FROM_EMAIL", "noreply@clinic.com")
        self.client = httpx.AsyncClient(timeout=10.0)

    def get_functions(self) -> List[Callable]:
        return [
            self.send_sms_confirmation,
            self.send_email_confirmation,
            self.send_reminder,
            self.send_intake_form_link,
        ]

    @llm.ai_callable(description="Send SMS booking confirmation")
    async def send_sms_confirmation(
        self,
        to_phone: str,
        patient_name: str,
        appointment_date: str,
        appointment_time: str,
        location: str = "123 Main St, Suite 200",
    ) -> str:
        if not all([self.twilio_sid, self.twilio_token, self.twilio_from]):
            return json.dumps({"status": "skipped", "reason": "twilio_not_configured"})
        try:
            body = (
                f"Hi {patient_name}, your appointment is confirmed for "
                f"{appointment_date} at {appointment_time}. "
                f"Location: {location}. Reply STOP to opt out."
            )
            auth = (self.twilio_sid, self.twilio_token)
            resp = await self.client.post(
                f"https://api.twilio.com/2010-04-01/Accounts/{self.twilio_sid}/Messages.json",
                data={"From": self.twilio_from, "To": to_phone, "Body": body},
                auth=auth,
            )
            resp.raise_for_status()
            return json.dumps({"status": "sent", "sid": resp.json().get("sid")})
        except Exception as e:
            return json.dumps({"error": str(e), "status": "failed"})

    @llm.ai_callable(description="Send email booking confirmation")
    async def send_email_confirmation(
        self,
        to_email: str,
        patient_name: str,
        appointment_date: str,
        appointment_time: str,
        location: str = "123 Main St, Suite 200",
        intake_form_url: str = "",
    ) -> str:
        if not self.sendgrid_key:
            return json.dumps({"status": "skipped", "reason": "sendgrid_not_configured"})
        try:
            html = f"""
            <h2>Appointment Confirmed</h2>
            <p>Hi {patient_name},</p>
            <p>Your appointment is scheduled for <strong>{appointment_date} at {appointment_time}</strong>.</p>
            <p>Location: {location}</p>
            {f'<p><a href="{intake_form_url}">Complete new patient forms here</a></p>' if intake_form_url else ''}
            <p>We look forward to seeing you!</p>
            """
            resp = await self.client.post(
                "https://api.sendgrid.com/v3/mail/send",
                headers={"Authorization": f"Bearer {self.sendgrid_key}", "Content-Type": "application/json"},
                json={
                    "personalizations": [{"to": [{"email": to_email}], "subject": "Appointment Confirmation"}],
                    "from": {"email": self.from_email, "name": "Clinic Reception"},
                    "content": [{"type": "text/html", "value": html}],
                },
            )
            resp.raise_for_status()
            return json.dumps({"status": "sent"})
        except Exception as e:
            return json.dumps({"error": str(e), "status": "failed"})

    @llm.ai_callable(description="Send appointment reminder (24h before)")
    async def send_reminder(
        self,
        to_phone: str,
        to_email: str,
        patient_name: str,
        appointment_date: str,
        appointment_time: str,
    ) -> str:
        results = []
        if self.twilio_sid:
            sms = await self.send_sms_confirmation(
                to_phone, patient_name, appointment_date, appointment_time
            )
            results.append(("sms", json.loads(sms).get("status")))
        if self.sendgrid_key:
            email = await self.send_email_confirmation(
                to_email, patient_name, appointment_date, appointment_time
            )
            results.append(("email", json.loads(email).get("status")))
        return json.dumps({"reminders": results})

    @llm.ai_callable(description="Send new patient intake form link via SMS")
    async def send_intake_form_link(
        self,
        to_phone: str,
        patient_name: str,
        form_url: str,
    ) -> str:
        if not all([self.twilio_sid, self.twilio_token, self.twilio_from]):
            return json.dumps({"status": "skipped", "reason": "twilio_not_configured"})
        try:
            body = f"Hi {patient_name}, please complete your new patient forms before your visit: {form_url}"
            auth = (self.twilio_sid, self.twilio_token)
            resp = await self.client.post(
                f"https://api.twilio.com/2010-04-01/Accounts/{self.twilio_sid}/Messages.json",
                data={"From": self.twilio_from, "To": to_phone, "Body": body},
                auth=auth,
            )
            resp.raise_for_status()
            return json.dumps({"status": "sent", "sid": resp.json().get("sid")})
        except Exception as e:
            return json.dumps({"error": str(e), "status": "failed"})

    async def close(self):
        await self.client.aclose()
